import type { GeospatialCamera } from "@babylonjs/lite";

export function tiltGlobeCamera(camera: GeospatialCamera, pitch: number): void {
  // Allow the requested tilt at any zoom level.
  camera.limits.pitchDisabledRadiusScale = null;

  const current = camera.pitch;
  if (current === pitch) {
    // Force a re-orientation (e.g. if center was changed in place) by making a
    // tiny transient pitch change and then returning to the requested value.
    const eps = 1e-6;
    const { pitchMin, pitchMax } = camera.limits;
    let transient: number | null = null;
    if (pitch + eps <= pitchMax) transient = pitch + eps;
    else if (pitch - eps >= pitchMin) transient = pitch - eps;
    if (transient !== null) {
      camera.pitch = transient;
      camera.pitch = pitch;
    }
    // If no transient is possible (bounds too tight), the value is already the
    // requested pitch; nothing else to do without touching other channels.
  } else {
    camera.pitch = pitch;
  }
}
```
